[{"order":1,"type":"heading","text":"Angular Route Parameters and Query Parameters"},{"order":2,"type":"paragraph","text":"In Angular, route parameters and query parameters are two common ways to pass data to components through the URL. They serve different purposes and are accessed differently within your application."},{"order":3,"type":"subheading","text":"Route Parameters"},{"order":4,"type":"paragraph","text":"Route parameters are used to identify a specific resource or a specific part of your application's state. They are defined as part of the route path itself. For example, '/products/:id' indicates that the route expects a parameter named 'id'."},{"order":5,"type":"paragraph","text":"To define a route with a parameter, you configure your Angular router module. Here's an example:"},{"order":6,"type":"code","text":"const routes: Routes = [
  { path: 'products/:id', component: ProductDetailComponent }
];"},{"order":7,"type":"paragraph","text":"In this example, ':id' is the route parameter. When a user navigates to a URL like '/products/123', the 'ProductDetailComponent' will be loaded, and the value '123' will be available as the 'id' parameter."},{"order":8,"type":"paragraph","text":"To access the route parameter within the component, you use the 'ActivatedRoute' service from '@angular/router'."},{"order":9,"type":"code","text":"import { Component, OnInit } from '@angular/core';
import { ActivatedRoute } from '@angular/router';

@Component({
  selector: 'app-product-detail',
  templateUrl: './product-detail.component.html',
  styleUrls: ['./product-detail.component.css']
})
export class ProductDetailComponent implements OnInit {
  productId: string | null = null;

  constructor(private route: ActivatedRoute) { }

  ngOnInit(): void {
    this.route.paramMap.subscribe(params => {
      this.productId = params.get('id');
      console.log('Product ID:', this.productId);
    });
  }
}"},{"order":10,"type":"paragraph","text":"In the code above, 'ActivatedRoute' is injected into the component's constructor. Inside 'ngOnInit', we subscribe to 'paramMap' to get the route parameters. The 'params.get('id')' method retrieves the value of the 'id' parameter. Note that 'params.get()' returns a string or null."},{"order":11,"type":"subheading","text":"Query Parameters"},{"order":12,"type":"paragraph","text":"Query parameters are optional key-value pairs appended to the URL after a question mark (?). They are used to pass non-hierarchical data to a component, such as filtering options, sorting preferences, or pagination details. For example, '/products?category=electronics&sort=price'."},{"order":13,"type":"paragraph","text":"Unlike route parameters, query parameters are not defined in the route configuration. They are simply appended to the URL."},{"order":14,"type":"paragraph","text":"To access query parameters within a component, you also use the 'ActivatedRoute' service."},{"order":15,"type":"code","text":"import { Component, OnInit } from '@angular/core';
import { ActivatedRoute } from '@angular/router';

@Component({
  selector: 'app-product-list',
  templateUrl: './product-list.component.html',
  styleUrls: ['./product-list.component.css']
})
export class ProductListComponent implements OnInit {
  category: string | null = null;
  sort: string | null = null;

  constructor(private route: ActivatedRoute) { }

  ngOnInit(): void {
    this.route.queryParamMap.subscribe(params => {
      this.category = params.get('category');
      this.sort = params.get('sort');
      console.log('Category:', this.category);
      console.log('Sort:', this.sort);
    });
  }
}"},{"order":16,"type":"paragraph","text":"In this code, we subscribe to 'queryParamMap' instead of 'paramMap'. The 'params.get('category')' and 'params.get('sort')' methods retrieve the values of the 'category' and 'sort' query parameters, respectively. Again, 'params.get()' returns a string or null."},{"order":17,"type":"subheading","text":"Navigating with Route and Query Parameters"},{"order":18,"type":"paragraph","text":"You can use the 'Router' service to navigate to routes with parameters. Here's how to navigate with route parameters:"},{"order":19,"type":"code","text":"import { Router } from '@angular/router';

constructor(private router: Router) { }

navigateToProduct(id: number) {
  this.router.navigate(['/products', id]);
}"},{"order":20,"type":"paragraph","text":"And here's how to navigate with query parameters:"},{"order":21,"type":"code","text":"import { Router, NavigationExtras } from '@angular/router';

constructor(private router: Router) { }

navigateToProducts(category: string, sort: string) {
  const navigationExtras: NavigationExtras = {
    queryParams: { 'category': category, 'sort': sort }
  };
  this.router.navigate(['/products'], navigationExtras);
}"},{"order":22,"type":"paragraph","text":"In the query parameter example, we use 'NavigationExtras' to specify the query parameters. The 'queryParams' property is an object containing the key-value pairs for the query parameters."},{"order":23,"type":"subheading","text":"Summary"},{"order":24,"type":"bullet_point","text":"Route parameters are used to identify specific resources and are part of the route path."},{"order":25,"type":"bullet_point","text":"Query parameters are used to pass optional data and are appended to the URL after a question mark."},{"order":26,"type":"bullet_point","text":"Both route parameters and query parameters can be accessed using the 'ActivatedRoute' service."},{"order":27,"type":"bullet_point","text":"Use the 'Router' service to navigate to routes with both route and query parameters."}]
